1	package clinical
2	
3	import (
4		"fmt"
5		"sort"
6		"strings"
7		"time"
8		"unicode/utf8"
9	)
10	
11	// Grant 由内部使用者为一名接收方建立针对某患者的整类读取授权。
12	//
13	// 这是 [Store.GrantSelective] 的整类形式：范围由明确的“就诊 + 类别
14	// （诊断/医嘱）”组合构成，覆盖各就诊+类别下的全部已生效记录（含授权
15	// 建立后才生效的记录）。不允许空范围，每个就诊都必须属于该患者
16	// （跨患者就诊会被拒绝），类别必须合法。时间窗为半开区间
17	// [startsAt, expiresAt)：开始时刻即生效，到截止时刻立即失效；
18	// 开始不早于截止时间（相等也算）一律拒绝。患者档案停用后不能新建授权。
19	// 授权与审计事件在同一次原子落盘中保留。
20	func (s *Store) Grant(actor Actor, patientID ID, receiverID string, scopes []Scope, startsAt, expiresAt time.Time) (Authorization, error) {
21		return s.GrantSelective(actor, patientID, receiverID, scopes, nil, startsAt, expiresAt)
22	}
23	
24	// GrantSelective 由内部使用者为一名接收方建立针对某患者的读取授权，
25	// 整类范围（scopes）与限定记录范围（selections）可以并存，同一条授权
26	// 可以包含多个就诊、类别。
27	//
28	// scopes 的每项按整类授权：覆盖该就诊+类别下全部已生效记录，并自然
29	// 包含授权后新增生效的记录；selections 的每项明确选出一条已生效记录，
30	// 被选记录更正后授权覆盖它的当前版本，但同一就诊同一类别的其他记录、
31	// 后来新增并生效的记录都不会自动进入限定范围。重复选择同一记录只算一次。
32	//
33	// scopes 与 selections 不能同时为空：空选择不代表整类授权。scope 中的
34	// 就诊必须存在且属于该患者，类别必须合法。每条 selection 都必须显式
35	// 声明记录所属的就诊与类别，且：记录不存在返回 ErrNotFound；记录属于
36	// 其他患者返回 ErrMismatchedPatient；空选择、空白或含无效 UTF-8 字节的
37	// 接收方标识、选择了尚未生效
38	// 的草稿、记录与声明的就诊或类别不符返回 ErrInvalidArgument。任一选择
39	// 不合法就拒绝整条授权：不保存合法部分，也不新增审计。
40	//
41	// 时间窗、停用档案与审计规则与 [Store.Grant] 相同。
42	func (s *Store) GrantSelective(actor Actor, patientID ID, receiverID string, scopes []Scope, selections []RecordSelection, startsAt, expiresAt time.Time) (Authorization, error) {
43		if !actor.valid() || !actor.IsInternal() {
44			return Authorization{}, ErrAccessDenied
45		}
46		if patientID == "" {
47			return Authorization{}, fmt.Errorf("%w: patient id is required", ErrInvalidArgument)
48		}
49		if strings.TrimSpace(receiverID) == "" {
50			return Authorization{}, fmt.Errorf("%w: receiver id is required", ErrInvalidArgument)
51		}
52		// 接收方标识必须是完整合法的 UTF-8：本地快照以 JSON 落盘，encoding/json
53		// 会把无效字节静默替换为 U+FFFD——若放行，重开后保存的标识与授权当次
54		// 返回的不同，授权会归到使用替换后标识的另一接收方名下。因此夹带任何
55		// 无效字节或不完整多字节字符的标识一律拒绝，绝不靠替换、截断或跳过坏
56		// 字节继续授权；用户明确输入的合法 U+FFFD 字符本身是合法 UTF-8，不受
57		// 此限制。
58		if !utf8.ValidString(receiverID) {
59			return Authorization{}, fmt.Errorf("%w: receiver id must be valid UTF-8", ErrInvalidArgument)
60		}
61		if len(scopes) == 0 && len(selections) == 0 {
62			return Authorization{}, fmt.Errorf("%w: authorization scope must not be empty", ErrInvalidArgument)
63		}
64		for _, sc := range scopes {
65			if sc.EncounterID == "" {
66				return Authorization{}, fmt.Errorf("%w: scope encounter id is required", ErrInvalidArgument)
67			}
68			if !validCategory(sc.Category) {
69				return Authorization{}, fmt.Errorf("%w: scope category must be %q or %q", ErrInvalidArgument, Diagnosis, Order)
70			}
71		}
72		for _, sel := range selections {
73			if strings.TrimSpace(sel.RecordID) == "" {
74				return Authorization{}, fmt.Errorf("%w: selection record id is required", ErrInvalidArgument)
75			}
76			if strings.TrimSpace(sel.EncounterID) == "" {
77				return Authorization{}, fmt.Errorf("%w: selection encounter id is required", ErrInvalidArgument)
78			}
79			if !validCategory(sel.Category) {
80				return Authorization{}, fmt.Errorf("%w: selection category must be %q or %q", ErrInvalidArgument, Diagnosis, Order)
81			}
82		}
83		if !startsAt.Before(expiresAt) {
84			return Authorization{}, fmt.Errorf("%w: starts-at must be strictly before expires-at", ErrInvalidArgument)
85		}
86	
87		var result Authorization
88		err := s.mutate(func(snap *snapshot) error {
89			if _, err := requireActivePatient(snap, patientID); err != nil {
90				return err
91			}
92	
93			// 去重并逐项校验整类范围：引用的就诊必须存在且属于该患者。
94			seenScope := map[Scope]bool{}
95			cleanedScopes := make([]Scope, 0, len(scopes))
96			for _, sc := range scopes {
97				if _, err := requireEncounter(snap, patientID, sc.EncounterID); err != nil {
98					return err
99				}
100				if seenScope[sc] {
101					continue
102				}
103				seenScope[sc] = true
104				cleanedScopes = append(cleanedScopes, sc)
105			}
106			sort.Slice(cleanedScopes, func(i, j int) bool {
107				if cleanedScopes[i].EncounterID != cleanedScopes[j].EncounterID {
108					return cleanedScopes[i].EncounterID < cleanedScopes[j].EncounterID
109				}
110				return cleanedScopes[i].Category < cleanedScopes[j].Category
111			})
112	
113			// 逐项校验限定范围：就诊必须属于该患者；记录必须存在、属于该患者、
114			// 已生效，且实际就诊与类别与声明一致。任一不合法即整体拒绝。
115			seenRecord := map[ID]bool{}
116			cleanedSelections := make([]RecordSelection, 0, len(selections))
117			for _, sel := range selections {
118				if _, err := requireEncounter(snap, patientID, sel.EncounterID); err != nil {
119					return err
120				}
121				r := snap.Records[sel.RecordID]
122				if r == nil {
123					return fmt.Errorf("%w: record %q", ErrNotFound, sel.RecordID)
124				}
125				if r.PatientID != patientID {
126					return fmt.Errorf("%w: record %q belongs to patient %q, not %q",
127						ErrMismatchedPatient, sel.RecordID, r.PatientID, patientID)
128				}
129				if r.CurrentVersionID == "" {
130					return fmt.Errorf("%w: record %q has no effective version; activate its draft first",
131						ErrInvalidArgument, sel.RecordID)
132				}
133				if r.EncounterID != sel.EncounterID || r.Category != sel.Category {
134					return fmt.Errorf("%w: record %q belongs to encounter %q category %q, not declared encounter %q category %q",
135						ErrInvalidArgument, sel.RecordID, r.EncounterID, r.Category, sel.EncounterID, sel.Category)
136				}
137				if seenRecord[sel.RecordID] {
138					// 重复选择同一记录只算一次。
139					continue
140				}
141				seenRecord[sel.RecordID] = true
142				cleanedSelections = append(cleanedSelections, sel)
143			}
144			sort.Slice(cleanedSelections, func(i, j int) bool {
145				return cleanedSelections[i].RecordID < cleanedSelections[j].RecordID
146			})
147	
148			now := s.now()
149			a := &Authorization{
150				ID:         newID("auth"),
151				PatientID:  patientID,
152				ReceiverID: receiverID,
153				Scopes:     cleanedScopes,
154				Selections: cleanedSelections,
155				StartsAt:   startsAt.UTC(),
156				ExpiresAt:  expiresAt.UTC(),
157				CreatedAt:  now,
158			}
159			snap.Authorizations[a.ID] = a
160			s.addAudit(snap, patientID, actor, ActionGranted, "authorization", a.ID, now)
161			result = cloneAuthorizationValue(a)
162			return nil
163		})
164		return result, err
165	}
166	
167	// Revoke 提前撤回授权。撤回在当前时间生效；此后该授权不再覆盖任何读取。
168	// 重复撤回返回成功且不产生额外变化（不新增审计事件、不改写撤回时间与操作
169	// 身份），与“停用”语义一致。确认只依据正式保存的撤回结果：即使本地保存
170	// 条件当前暂时不可用，合法的重复撤回也成功返回已有结果，不再尝试写盘；
171	// 但授权尚未撤回时若保存失败，仍明确返回保存错误。撤回其他患者的授权 ID
172	// 会得到 ErrMismatchedPatient/ErrNotFound（与授权是否已撤回无关）。
173	func (s *Store) Revoke(actor Actor, patientID, authorizationID ID) error {
174		if !actor.valid() || !actor.IsInternal() {
175			return ErrAccessDenied
176		}
177		return s.mutate(func(snap *snapshot) error {
178			a := snap.Authorizations[authorizationID]
179			if a == nil {
180				return fmt.Errorf("%w: authorization %q", ErrNotFound, authorizationID)
181			}
182			if a.PatientID != patientID {
183				return fmt.Errorf("%w: authorization %q belongs to patient %q, not %q",
184					ErrMismatchedPatient, authorizationID, a.PatientID, patientID)
185			}
186			if a.RevokedAt != nil {
187				// 幂等：正式保存的授权已经撤回。确认已有结果即可——保持首次撤回
188				// 的时间与操作身份、原接收方/范围/有效期，不生成额外变化或事件，
189				// 也不落盘：重复确认不依赖当前能否写入本地数据，任何内部使用者
190				// 的合法确认都得到同一结果，且不能把撤回时间更新到本次调用时刻。
191				return errUnchanged
192			}
193			now := s.now()
194			a.RevokedAt = &now
195			s.addAudit(snap, patientID, actor, ActionRevoked, "authorization", a.ID, now)
196			return nil
197		})
198	}
199	
200	// GetAuthorization 返回单个授权。仅供内部使用者。
201	func (s *Store) GetAuthorization(actor Actor, patientID, authorizationID ID) (Authorization, error) {
202		if !actor.valid() || !actor.IsInternal() {
203			return Authorization{}, ErrAccessDenied
204		}
205		var result Authorization
206		err := s.view(func(snap *snapshot) error {
207			a := snap.Authorizations[authorizationID]
208			if a == nil {
209				return fmt.Errorf("%w: authorization %q", ErrNotFound, authorizationID)
210			}
211			if a.PatientID != patientID {
212				return fmt.Errorf("%w: authorization %q belongs to patient %q, not %q",
213					ErrMismatchedPatient, authorizationID, a.PatientID, patientID)
214			}
215			result = cloneAuthorizationValue(a)
216			return nil
217		})
218		return result, err
219	}
220	
221	// ListAuthorizations 列出某患者（可选：某接收方）的全部授权，含已撤回者。
222	// 仅供内部使用者。
223	func (s *Store) ListAuthorizations(actor Actor, patientID ID, receiverID string) ([]Authorization, error) {
224		if !actor.valid() || !actor.IsInternal() {
225			return nil, ErrAccessDenied
226		}
227		var result []Authorization
228		err := s.view(func(snap *snapshot) error {
229			if _, err := requirePatient(snap, patientID); err != nil {
230				return err
231			}
232			for _, a := range snap.Authorizations {
233				if a.PatientID != patientID {
234					continue
235				}
236				if receiverID != "" && a.ReceiverID != receiverID {
237					continue
238				}
239				result = append(result, cloneAuthorizationValue(a))
240			}
241			sort.Slice(result, func(i, j int) bool { return result[i].ID < result[j].ID })
242			return nil
243		})
244		return result, err
245	}
246	
247	// Read 供接收方按自己的身份读取某次就诊下某个类别（诊断/医嘱）的内容。
248	//
249	// 结果是该接收方在“本次读取时间”所有当前有效授权允许记录的合集。“本次读取
250	// 时间”指真正开始核对权限的时刻：请求发出后若因等待同一存储上的其他操作而
251	// 排队，以等待结束、开始核对时的同一时刻统一判断本次涉及的各条授权是否有效，
252	// 等待本身不会延长或推迟授权的有效期。每条记录
253	// 只出现一次并按记录标识稳定排序：授权必须属于该接收方与该患者、已开始、
254	// 未到期且未撤回；整类范围（Scope）允许该就诊+类别下的全部已生效记录
255	// （含授权后才生效者），限定范围（RecordSelection）仅允许明确选中的记录。
256	// 同一条记录被多条授权（含整类与限定重叠）允许也只出现一次；被选记录被
257	// 更正后读取其当前生效版本。看不到草稿、旧版本或更正原因。
258	//
259	// 若不存在任何覆盖所请求就诊+类别的有效授权（全部尚未开始、已到期或已
260	// 撤回），或患者档案已停用，返回 ErrAccessDenied：结果中不含任何未授权
261	// 记录的标识、数量或内容。撤回整类授权后，只剩其他有效授权明确允许的记录。
262	func (s *Store) Read(actor Actor, patientID, encounterID ID, category string) (ReadResult, error) {
263		if !actor.valid() || actor.Kind != "receiver" {
264			return ReadResult{}, ErrAccessDenied
265		}
266		if patientID == "" || encounterID == "" {
267			return ReadResult{}, fmt.Errorf("%w: patient and encounter ids are required", ErrInvalidArgument)
268		}
269		if !validCategory(category) {
270			return ReadResult{}, fmt.Errorf("%w: category must be %q or %q", ErrInvalidArgument, Diagnosis, Order)
271		}
272	
273		var out ReadResult
274		err := s.view(func(snap *snapshot) error {
275			// 查阅时刻在进入临界区、真正开始核对权限时才取样：请求发出后若因
276			// 等待其他操作而排队，等待时间不能延长或推迟授权的有效判断——
277			// 本次读取涉及的所有授权统一按这同一时刻判断是否有效。
278			now := s.now()
279			// 合并该患者、该接收方所有当前有效授权的覆盖：整类范围与限定范围的
280			// 解释与创建交换共用同一套判定（grantCoverage），不在这里另写一份。
281			// 不提前区分“对象不存在/属于他人”与“无授权”，统一返回拒绝，从而不
282			// 向接收方泄露患者或就诊是否存在。
283			coverage := newGrantCoverage()
284			patientDeactivated := false
285			if p := snap.Patients[patientID]; p != nil {
286				patientDeactivated = p.Deactivated
287			}
288			for _, a := range snap.Authorizations {
289				if a.PatientID != patientID || a.ReceiverID != actor.ID {
290					continue
291				}
292				if !a.ActiveAt(now) {
293					// 未开始、已到期或已撤回的授权不参与覆盖。
294					continue
295				}
296				coverage.add(a)
297			}
298			if patientDeactivated || !coverage.coversRequest(encounterID, category) {
299				// 无授权、未开始、已到期、已撤回或档案停用：明确拒绝，
300				// 结果中不含任何受保护内容。整类授权覆盖该就诊+类别但其中暂时
301				// 没有生效记录时，coversRequest 仍为真，随后成功返回空集合，
302				// 不会把“有授权无记录”误判成拒绝。
303				return ErrAccessDenied
304			}
305	
306			// 能被授权覆盖的就诊必然属于该患者（Grant 时已校验），
307			// 此处再确认一次以防任何不一致状态。
308			e := snap.Encounters[encounterID]
309			if e == nil || e.PatientID != patientID {
310				return ErrAccessDenied
311			}
312	
313			out.EncounterID = encounterID
314			out.Category = category
315			var recs []EffectiveRecord
316			for _, r := range snap.Records {
317				if r.EncounterID != encounterID || r.Category != category || r.PatientID != patientID {
318					continue
319				}
320				// 整类范围覆盖全部（含授权后才生效者）；限定范围只覆盖明确选中
321				// 的记录，同类其他记录与后来新增记录不被覆盖。多条授权、整类与
322				// 限定重叠时同一条记录只出现一次。
323				if !coverage.coversRecord(r) {
324					continue
325				}
326				if eff, ok := currentEffective(snap, r); ok {
327					recs = append(recs, eff)
328				}
329				// 仅有草稿、尚无生效版本的记录天然不出现；
330				// 限定授权选中的记录在授权后也不会退回草稿状态。
331			}
332			sort.Slice(recs, func(i, j int) bool { return recs[i].RecordID < recs[j].RecordID })
333			out.Records = recs
334			return nil
335		})
336		return out, err
337	}
338	
339	// cloneAuthorizationValue 返回授权的深拷贝：整类范围、限定范围与撤回时间
340	// 都与库内保存的对象各自独立。返回给调用方的授权只是本次操作得到的信息；
341	// 调用方在本地修改它（改范围、换记录标识、改撤回时间）不能改变库内正式
342	// 保存的授权，从同一授权取得的多份结果也互不影响。
343	func cloneAuthorizationValue(a *Authorization) Authorization {
344		out := *a
345		out.Scopes = append([]Scope(nil), a.Scopes...)
346		out.Selections = append([]RecordSelection(nil), a.Selections...)
347		if a.RevokedAt != nil {
348			t := *a.RevokedAt
349			out.RevokedAt = &t
350		}
351		return out
352	}
353

